package edu.pe.cibertec.saibm.usuario.infrastructure.config; import java.util.*; import edu.pe.cibertec.saibm.usuario.application.port.in.*; import edu.pe.cibertec.saibm.usuario.application.usecase.UserService; @org.springframework.transaction.annotation.Transactional public class UserTransactionalFacade implements UserUseCase {private final UserService service;public UserTransactionalFacade(UserService s){service=s;}public UserView create(UserCommand c,String x){return service.create(c,x);}public UserView find(UUID id,Actor a){return service.find(id,a);}public List<UserView> list(String q,Actor a){return service.list(q,a);}public UserView update(UUID id,UserCommand c,Actor a,String x){return service.update(id,c,a,x);}public void deactivate(UUID id,Actor a,String x){service.deactivate(id,a,x);}public void reactivate(UUID id,Actor a,String x){service.reactivate(id,a,x);}}
